public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value != null) {
        return substVars(value, props);
    }
    return null;
}

private static String substVars(String value, Properties props) {
    int start = value.indexOf("${");
    if (start == -1) {
        return value;
    }
    StringBuilder result = new StringBuilder();
    int end = -1;
    while (start != -1) {
        result.append(value, end + 1, start);
        end = value.indexOf("}", start);
        if (end == -1) {
            break;
        }
        String varName = value.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        } else {
            result.append("${").append(varName).append("}");
        }
        start = value.indexOf("${", end);
    }
    result.append(value.substring(end + 1));
    return result.toString();
}

