import java.util.Stack;

private void pop(final String descriptor) {
    Stack<String> stack = new Stack<>();
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int semiColonIndex = descriptor.indexOf(';', i);
            stack.push(descriptor.substring(i, semiColonIndex + 1));
            i = semiColonIndex + 1;
        } else if (c == '[') {
            int closeBracketIndex = descriptor.indexOf(']', i);
            stack.push(descriptor.substring(i, closeBracketIndex + 1));
            i = closeBracketIndex + 1;
        } else if (c == '(') {
            int closeParenthesisIndex = descriptor.indexOf(')', i);
            stack.push(descriptor.substring(i, closeParenthesisIndex + 1));
            i = closeParenthesisIndex + 1;
        } else {
            stack.push(String.valueOf(c));
            i++;
        }
    }
    while (!stack.isEmpty()) {
        stack.pop();
    }
}

