        Set<V> remainingVertices = new HashSet<>(vertices);
        remainingVertices.remove(vertex);

        for (V v : remainingVertices) {
            if (!graph.containsEdge(vertex, v)) {
                return false;
            }
        }

        return isClique(graph, remainingVertices);
    }
}

import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

private List<Integer> computeLowerBounds(List<Integer> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }
    keys.sort(Comparator.naturalOrder());
    int min = keys.get(0);
    for (int key : keys) {
        if (key > min) {
            lowerBounds.add(min);
            min = key;
        }
    }
    lowerBounds.add(min);
    return lowerBounds;
}

import java.util.Stack;

private void pop(final String descriptor) {
    Stack<String> stack = new Stack<>();
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int semiColonIndex = descriptor.indexOf(';', i);
            stack.push(descriptor.substring(i, semiColonIndex + 1));
            i = semiColonIndex + 1;
        } else if (c == '[') {
            int closeBracketIndex = descriptor.indexOf(']', i);
            stack.push(descriptor.substring(i, closeBracketIndex + 1));
            i = closeBracketIndex + 1;
        } else if (c == '(') {
            int closeParenthesisIndex = descriptor.indexOf(')', i);
            stack.push(descriptor.substring(i, closeParenthesisIndex + 1));
            i = closeParenthesisIndex + 1;
        } else {
            stack.push(String.valueOf(c));
            i++;
        }
    }
    while (!stack.isEmpty()) {
        stack.pop();
    }
}

