import java.io.IOException;
import java.io.InputStream;

public class ProtocolBufferReader {
    private InputStream inputStream;

    public ProtocolBufferReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    public int readTag() throws IOException {
        int firstByte = inputStream.read();
        if (firstByte == -1) {
            return 0;
        }
        int tag = (firstByte & 0x7F) << 3;
        int shift = 7;
        while ((firstByte & 0x80) != 0) {
            firstByte = inputStream.read();
            if (firstByte == -1) {
                throw new IOException("Protocol message contained a tag with invalid wire type.");
            }
            tag |= (firstByte & 0x7F) << shift;
            shift += 7;
        }
        return tag;
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector put11(final int byteValue1, final int byteValue2) {
        if (size + 2 > data.length) {
            data = Arrays.copyOf(data, data.length * 2);
        }
        data[size++] = (byte) byteValue1;
        data[size++] = (byte) byteValue2;
        return this;
    }

    @Override
    public String toString() {
        return Arrays.toString(Arrays.copyOf(data, size));
    }

    public static void main(String[] args) {
        ByteVector vector = new ByteVector();
        vector.put11(0x12, 0x34);
        System.out.println(vector); // Output: [18, 52]
    }
}

